"use client"

import { useState, useEffect } from "react"
import Link from "next/link"
import { trainerService } from "@/lib/trainer-service"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { MapPin, Calendar, Clock, X, CheckCircle, AlertCircle, Filter, Loader2 } from "lucide-react"
import { formatDate, formatTime } from "@/lib/utils"
import { toast } from "sonner"

export default function TrainerRoomBookingsPage() {
  const [bookings, setBookings] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState("")
  const [filter, setFilter] = useState<string>("all")
  const [showCancelDialog, setShowCancelDialog] = useState(false)
  const [selectedBooking, setSelectedBooking] = useState<any | null>(null)

  useEffect(() => {
    fetchBookings()
  }, [])

  const fetchBookings = async () => {
    try {
      setLoading(true)
      const data = await trainerService.getRoomBookings()
      setBookings(data)
    } catch (err: any) {
      setError(err?.response?.data?.message || "فشل في جلب طلبات الحجز")
      toast.error("حدث خطأ أثناء تحميل طلبات الحجز")
    } finally {
      setLoading(false)
    }
  }

  const filteredBookings = bookings.filter(booking => {
    if (filter === "all") return true
    const status = booking.status.toLowerCase()
    if (filter === "pending") return status === "pending_approval" || status === "pending_payment"
    return status === filter
  })

  const getStatusLabel = (status: string) => {
    const s = status.toLowerCase()
    switch (s) {
      case 'pending_approval': return 'بانتظار الموافقة'
      case 'pending_payment': return 'بانتظار الدفع'
      case 'approved': return 'مقبول'
      case 'rejected': return 'مرفوض'
      case 'cancelled': return 'ملغى'
      default: return status
    }
  }

  const getStatusColor = (status: string) => {
    const s = status.toLowerCase()
    switch (s) {
      case 'pending_approval': return 'text-amber-600 border-amber-200 bg-amber-50'
      case 'pending_payment': return 'text-blue-600 border-blue-200 bg-blue-50'
      case 'approved': return 'text-green-600 border-green-200 bg-green-50'
      case 'rejected': return 'text-red-600 border-red-200 bg-red-50'
      case 'cancelled': return 'text-gray-600 border-gray-200 bg-gray-50'
      default: return 'text-gray-600 border-gray-200 bg-gray-50'
    }
  }

  const getStatusIcon = (status: string) => {
    const s = status.toLowerCase()
    if (s.startsWith('pending')) return <Clock className="h-4 w-4" />
    switch (s) {
      case 'approved': return <CheckCircle className="h-4 w-4" />
      case 'rejected': return <X className="h-4 w-4" />
      case 'cancelled': return <AlertCircle className="h-4 w-4" />
      default: return null
    }
  }

  const handleCancelBooking = (booking: any) => {
    setSelectedBooking(booking)
    setShowCancelDialog(true)
  }

  const confirmCancellation = async () => {
    if (!selectedBooking) return

    // Note: Cancel booking logic not yet fully implemented in trainerService
    // For now, we update local state after potentially calling an API
    toast.info("سيتم تنفيذ إلغاء الحجز قريباً")
    setShowCancelDialog(false)
    setSelectedBooking(null)
  }

  const handleConfirmPayment = (booking: any) => {
    // Redirect to course edit or dedicated resubmit page if rejected
    // For pending_payment, usually it's already submitted or handled during course creation
    toast.info("سيتم توجيهك لصفحة إرفاق الإيصال")
  }

  const pendingCount = bookings.filter(b => b.status.toLowerCase().startsWith('pending')).length
  const approvedCount = bookings.filter(b => b.status.toLowerCase() === 'approved').length
  const rejectedCount = bookings.filter(b => b.status.toLowerCase() === 'rejected').length

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <Loader2 className="h-10 w-10 animate-spin text-primary opacity-50" />
        <p className="text-slate-500 font-medium">جاري تحميل طلبات الحجز...</p>
      </div>
    )
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8" dir="rtl">
      {/* Header */}
      <div className="mb-8 text-right">
        <h1 className="text-3xl font-black text-[#1e293b] mb-2 leading-tight">
          طلبات حجز القاعات
        </h1>
        <p className="text-slate-500 font-bold text-sm">
          إدارة ومتابعة طلبات حجز القاعات لدوراتك التدريبية
        </p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-10">
        <Card className="rounded-[2rem] border-0 shadow-sm bg-amber-50/30 overflow-hidden">
          <CardContent className="pt-8 pb-8 flex items-center justify-between px-8">
            <div className="text-right">
              <p className="text-[12px] font-black text-amber-600 uppercase tracking-wider mb-1">قيد المراجعة</p>
              <p className="text-3xl font-black text-slate-900">{pendingCount}</p>
            </div>
            <div className="p-4 bg-amber-100/50 text-amber-600 rounded-[1.5rem]">
              <Clock className="h-8 w-8" />
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-[2rem] border-0 shadow-sm bg-green-50/30 overflow-hidden">
          <CardContent className="pt-8 pb-8 flex items-center justify-between px-8">
            <div className="text-right">
              <p className="text-[12px] font-black text-green-600 uppercase tracking-wider mb-1">مقبولة</p>
              <p className="text-3xl font-black text-slate-900">{approvedCount}</p>
            </div>
            <div className="p-4 bg-green-100/50 text-green-600 rounded-[1.5rem]">
              <CheckCircle className="h-8 w-8" />
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-[2rem] border-0 shadow-sm bg-red-50/30 overflow-hidden">
          <CardContent className="pt-8 pb-8 flex items-center justify-between px-8">
            <div className="text-right">
              <p className="text-[12px] font-black text-red-600 uppercase tracking-wider mb-1">مرفوضة</p>
              <p className="text-3xl font-black text-slate-900">{rejectedCount}</p>
            </div>
            <div className="p-4 bg-red-100/50 text-red-600 rounded-[1.5rem]">
              <X className="h-8 w-8" />
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-[2rem] border-0 shadow-sm bg-blue-50/30 overflow-hidden">
          <CardContent className="pt-8 pb-8 flex items-center justify-between px-8">
            <div className="text-right">
              <p className="text-[12px] font-black text-blue-600 uppercase tracking-wider mb-1">إجمالي الطلبات</p>
              <p className="text-3xl font-black text-slate-900">{bookings.length}</p>
            </div>
            <div className="p-4 bg-blue-100/50 text-blue-600 rounded-[1.5rem]">
              <MapPin className="h-8 w-8" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filter */}
      <div className="mb-6 flex items-center gap-4 bg-white p-4 rounded-3xl border border-slate-100 shadow-sm">
        <Filter className="h-5 w-5 text-slate-400 mr-2" />
        <Select value={filter} onValueChange={setFilter}>
          <SelectTrigger className="w-48 rounded-2xl border-slate-100 h-10 font-bold text-slate-600">
            <SelectValue placeholder="تصفية" />
          </SelectTrigger>
          <SelectContent className="rounded-2xl border-slate-100">
            <SelectItem value="all">جميع الحالات</SelectItem>
            <SelectItem value="pending">قيد المعالجة</SelectItem>
            <SelectItem value="approved">مقبولة</SelectItem>
            <SelectItem value="rejected">مرفوضة</SelectItem>
            <SelectItem value="cancelled">ملغاة</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Bookings Table */}
      <Card className="rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <CardContent className="p-0">
          {filteredBookings.length === 0 ? (
            <div className="text-center py-20 px-6">
              <div className="bg-slate-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
                <MapPin className="h-10 w-10 text-slate-300" />
              </div>
              <h3 className="text-xl font-black text-slate-900 mb-2">
                لا توجد طلبات حجز
              </h3>
              <p className="text-slate-400 font-bold text-sm">
                لم يتم العثور على أي طلبات حجز مطابقة للمعايير المحددة
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader className="bg-slate-50/50">
                  <TableRow className="hover:bg-transparent border-slate-50">
                    <TableHead className="text-right h-14 font-black text-slate-500 text-[11px] uppercase px-8">الدورة</TableHead>
                    <TableHead className="text-right h-14 font-black text-slate-500 text-[11px] uppercase">التاريخ والوقت</TableHead>
                    <TableHead className="text-right h-14 font-black text-slate-500 text-[11px] uppercase">القاعة والمعهد</TableHead>
                    <TableHead className="text-right h-14 font-black text-slate-500 text-[11px] uppercase">التكلفة</TableHead>
                    <TableHead className="text-right h-14 font-black text-slate-500 text-[11px] uppercase text-center px-8">الحالة</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredBookings.map((booking) => (
                    <TableRow key={booking.id} className="border-slate-50 hover:bg-slate-50/30 transition-colors">
                      <TableCell className="px-8 py-5">
                        <div className="flex flex-col">
                          <span className="font-black text-slate-900 text-sm whitespace-nowrap">{booking.course?.title || "دورة غير محددة"}</span>
                          <span className="text-[11px] text-slate-400 font-bold mt-1">الغرض: {booking.purpose || "حجز عام"}</span>
                        </div>
                      </TableCell>
                      <TableCell className="py-5">
                        <div className="flex flex-col gap-1.5">
                          <div className="flex items-center gap-2 text-sm font-black text-slate-700">
                            <Calendar className="h-3.5 w-3.5 text-blue-500 opacity-60" />
                            {formatDate(booking.startDate)}
                          </div>
                          <div className="flex items-center gap-2 text-[11px] font-bold text-slate-400">
                            <Clock className="h-3.5 w-3.5" />
                            {formatTime(booking.defaultStartTime)} - {formatTime(booking.defaultEndTime)}
                          </div>
                        </div>
                      </TableCell>
                      <TableCell className="py-5">
                        <div className="flex flex-col gap-1.5">
                          <Link href={`/trainer/halls/${booking.roomId}`} className="flex items-center gap-2 text-sm font-black text-blue-600 hover:text-blue-700">
                            <MapPin className="h-3.5 w-3.5 opacity-60" />
                            {booking.room?.name || "قاعة غير معروفة"}
                          </Link>
                          <span className="text-[11px] text-slate-400 font-bold me-5">{booking.room?.institute?.name || "معهد غير محدد"}</span>
                        </div>
                      </TableCell>
                      <TableCell className="py-5">
                        <div className="text-sm font-black text-slate-900">
                          {new Intl.NumberFormat('en-US').format(booking.totalPrice)} ريـال
                        </div>
                      </TableCell>
                      <TableCell className="px-8 py-5 text-center">
                        <Badge variant="outline" className={`rounded-full px-4 py-1 text-[10px] font-black border-2 flex items-center gap-2 mx-auto w-fit ${getStatusColor(booking.status)}`}>
                          {getStatusIcon(booking.status)}
                          {getStatusLabel(booking.status)}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Help Card */}
      <Card className="mt-10 rounded-[2.5rem] border-0 bg-blue-600 p-10 text-white relative overflow-hidden shadow-xl shadow-blue-200">
        <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 gap-10">
          <div className="text-right">
            <h3 className="text-2xl font-black mb-4">كيفية طلب حجز قاعة؟</h3>
            <ul className="space-y-4 text-sm font-bold opacity-90">
              <li className="flex items-center gap-3 justify-end">
                قم بإضافة درس حضوري في جدول الدورة عند إنشائها
                <CheckCircle className="h-5 w-5 text-blue-300" />
              </li>
              <li className="flex items-center gap-3 justify-end">
                اختر القاعة المناسبة من قائمة القاعات المتاحة
                <CheckCircle className="h-5 w-5 text-blue-300" />
              </li>
              <li className="flex items-center gap-3 justify-end">
                قم بإرفاق إيصال الدفع لقيمة حجز القاعة
                <CheckCircle className="h-5 w-5 text-blue-300" />
              </li>
            </ul>
          </div>
          <div className="flex flex-col justify-center items-end">
            <div className="bg-white/20 p-6 rounded-[2rem] backdrop-blur-sm border border-white/20 max-w-sm text-right">
              <AlertCircle className="h-10 w-10 text-blue-200 mb-4" />
              <p className="text-sm leading-relaxed font-bold">
                سيقوم مالك المعهد بمراجعة طلب الحجز الخاص بك والموافقة عليه بعد التحقق من إيصال الدفع وتوفر القاعة. ستبقى الدورة كمسودة حتى الموافقة النهائية.
              </p>
            </div>
          </div>
        </div>
        {/* Decoration */}
        <div className="absolute top-[-100px] right-[-100px] w-64 h-64 bg-blue-500 rounded-full blur-[100px] opacity-50"></div>
        <div className="absolute bottom-[-100px] left-[-100px] w-64 h-64 bg-blue-400 rounded-full blur-[100px] opacity-30"></div>
      </Card>
    </div>
  )
}
